import SwiftUI
import WebKit
import AVFoundation
import AudioToolbox
import UIKit

@main
struct TheBombGameApp: App {
    init() {
        try? AVAudioSession.sharedInstance().setCategory(.playback, mode: .default, options: [.mixWithOthers])
        try? AVAudioSession.sharedInstance().setActive(true)
    }

    var body: some Scene {
        WindowGroup {
            BombGameProWebView()
                .ignoresSafeArea()
                .preferredColorScheme(.dark)
                .statusBarHidden(true)
        }
    }
}

final class HapticsCoordinator: NSObject, WKScriptMessageHandler {
    func userContentController(_ userContentController: WKUserContentController, didReceive message: WKScriptMessage) {
        guard let body = message.body as? String else { return }
        switch body {
        case "light":
            let gen = UIImpactFeedbackGenerator(style: .medium)
            gen.impactOccurred()
        case "heavy":
            let gen = UIImpactFeedbackGenerator(style: .heavy)
            gen.impactOccurred()
            AudioServicesPlaySystemSound(1104)
        case "boom":
            let notif = UINotificationFeedbackGenerator()
            notif.notificationOccurred(.error)
            AudioServicesPlaySystemSound(kSystemSoundID_Vibrate)
        default:
            break
        }
    }
}

struct BombGameProWebView: UIViewRepresentable {
    private static let embeddedHTMLBase64 = ""

    func makeCoordinator() -> HapticsCoordinator {
        HapticsCoordinator()
    }

    func makeUIView(context: Context) -> WKWebView {
        let config = WKWebViewConfiguration()
        config.allowsInlineMediaPlayback = true
        config.mediaTypesRequiringUserActionForPlayback = []
        config.userContentController.add(context.coordinator, name: "haptics")

        let webView = WKWebView(frame: .zero, configuration: config)
        webView.isOpaque = false
        webView.backgroundColor = UIColor(red: 0.06, green: 0.02, blue: 0.12, alpha: 1.0)
        webView.scrollView.backgroundColor = webView.backgroundColor
        webView.scrollView.isScrollEnabled = false
        webView.scrollView.bounces = false
        webView.scrollView.contentInsetAdjustmentBehavior = .never

        if let data = Data(base64Encoded: Self.embeddedHTMLBase64),
           let htmlString = String(data: data, encoding: .utf8) {
            webView.loadHTMLString(htmlString, baseURL: nil)
        }
        return webView
    }

    func updateUIView(_ uiView: WKWebView, context: Context) {}
}
